export type JobStatus = "awaiting" | "approved" | "rejected" | "expired";

export interface Job {
  id: string;
  title: string;
  status: JobStatus;
  approvedAt?: number;
}

/** An approval is single-use and expires after five minutes. */
export const APPROVAL_TTL_MS = 5 * 60 * 1000;

export function describeStatus(job: Job): string {
  switch (job.status) {
    case "awaiting":
      return "Waiting for your approval";
    case "approved":
      return "Approved for one run";
    case "rejected":
      return "Rejected — nothing was executed";
    case "expired":
      return "Approval expired — approve again to run";
  }
}

export function canRun(job: Job, now = Date.now()): boolean {
  if (job.status !== "approved" || job.approvedAt === undefined) return false;
  return now - job.approvedAt < APPROVAL_TTL_MS;
}

