import { describe, expect, it } from "vitest";
import { APPROVAL_TTL_MS, canRun, describeStatus, type Job } from "../src/lib/approvals";

const job = (status: Job["status"], approvedAt?: number): Job => ({ id: "job-1", title: "Refactor header", status, approvedAt });

describe("approvals", () => {
  it("only runs approved jobs", () => {
    expect(canRun(job("approved", 0), 1_000)).toBe(true);
    expect(canRun(job("awaiting"), 1_000)).toBe(false);
  });

  it("expires an approval after the TTL", () => {
    expect(canRun(job("approved", 0), APPROVAL_TTL_MS + 1)).toBe(false);
  });

  it("describes a rejected job honestly", () => {
    expect(describeStatus(job("rejected"))).toContain("nothing was executed");
  });
});

