import { APPROVAL_TTL_MS } from "../lib/approvals";

export function ApprovalTimer({ approvedAt, now }: { approvedAt: number; now: number }) {
  const remaining = Math.max(0, APPROVAL_TTL_MS - (now - approvedAt));
  return <span className="timer">{Math.ceil(remaining / 1000)}s left</span>;
}
